        @Override public SchemaLocation getSchemaLocation() { return null; }
        @Override public JsonSchema getRefSchema() { return null; }
        @Override public JsonSchema getSchemaByReference(String ref) { return null; }
        @Override public JsonSchema getSchemaByPath(String path) { return null; }
        @Override public Set<ValidationMessage> validate(JsonNode node) { return Set.of(); }
        @Override public Set<ValidationMessage> validate(ExecutionContext executionContext, JsonNode node) { return Set.of(); }
