        @Override public String getKeyword() { return null; }
        @Override public JsonNodePath getEvaluationPath() { return null; }
        @Override public String getSchemaPath() { return null; }
        @Override public String getRef() { return null; }
        @Override public Object getReference() { return null; }
        @Override public Map<String, JsonSchema> getSchemas() { return null; }
        @Override public List<JsonSchema> getItems() { return null; }
        @Override public JsonSchema getAdditionalProperties() { return null; }
        @Override public JsonSchema getAdditionalItems() { return null; }
        @Override public JsonSchema getContains() { return null; }
        @Override public JsonSchema getIfSchema() { return null; }
        @Override public JsonSchema getThenSchema() { return null; }
        @Override public JsonSchema getElseSchema() { return null; }
        @Override public JsonSchema getNotSchema() { return null; }
