class TestJsonSchema implements JsonSchema {
   private final AtomicInteger initCount = new AtomicInteger(0);
   private RuntimeException toThrow;
   private Runnable onInit;

   public TestJsonSchema() {}
   public void setThrow(RuntimeException e) { this.toThrow = e; }
   public void setOnInit(Runnable r) { this.onInit = r; }
   @Override
   public void initializeValidators() {
        initCount.incrementAndGet();
        if (onInit != null) onInit.run();
        if (toThrow != null) throw toThrow;
   }
   public int getInitCount() { return initCount.get(); }
   // other methods stubbed
}

